export declare const cssText = "\n.dsh_market_section {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  max-width: 760px;\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_headingRow {\n  display: flex;\n  align-items: baseline;\n  gap: 16px;\n  min-width: 0;\n}\n.dsh_market_headerAction {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  flex: none;\n  padding: 2px 4px;\n  border: 0;\n  border-radius: 4px;\n  background: none;\n  color: var(--dsw-alias-label-tertiary);\n  font: inherit;\n  font-size: 12px;\n  line-height: 18px;\n  white-space: nowrap;\n  cursor: pointer;\n}\n.dsh_market_headerAction:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_headerAction:focus-visible {\n  outline: 2px solid var(--dsw-alias-state-business-primary);\n  outline-offset: 2px;\n}\n.dsh_market_headerAction:disabled {\n  cursor: default;\n  opacity: .55;\n}\n.dsh_market_heading {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin: 0;\n  font-size: 18px;\n  font-weight: 600;\n}\n/* The market's own version, beside its name: a fact about the deployment,\n   so it reads at the weight of one rather than of the title. */\n.dsh_market_selfVersion {\n  font-size: 12px;\n  font-weight: 400;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsw-alias-label-tertiary);\n}\n/* The section's own page strip, in the official tab language. */\n.dsh_market_tabs {\n  display: flex;\n  align-items: flex-end;\n  gap: 22px;\n  margin-top: 2px;\n  border-bottom: 1px solid var(--dsw-alias-border-l2);\n}\n.dsh_market_tab {\n  position: relative;\n  padding: 7px 1px 9px;\n  border: 0;\n  background: none;\n  color: var(--dsw-alias-label-tertiary);\n  font: inherit;\n  font-size: 13px;\n  line-height: 20px;\n  cursor: pointer;\n}\n.dsh_market_tab:hover,\n.dsh_market_tab[data-active=\"true\"] {\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_tab[data-active=\"true\"]::after,\n.dsh_market_tab:focus-visible::after {\n  content: \"\";\n  position: absolute;\n  right: 0;\n  bottom: -1px;\n  left: 0;\n  height: 2px;\n  border-radius: 2px 2px 0 0;\n  background: var(--dsw-alias-label-primary);\n}\n.dsh_market_tab:focus-visible {\n  border-radius: 2px;\n  outline: 2px solid var(--dsw-alias-state-business-primary);\n  outline-offset: 2px;\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_page {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  min-width: 0;\n  padding-top: 12px;\n}\n\n/* The off state: one card that explains itself and asks. */\n.dsh_market_intro {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 16px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 10px;\n  background: var(--dsw-alias-bg-layer-3);\n}\n.dsh_market_introTitle {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 22px;\n}\n.dsh_market_introSlogan,\n.dsh_market_pageSlogan {\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 22px;\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_introBody,\n.dsh_market_disclaimer {\n  margin: 0;\n  font-size: 13px;\n  line-height: 20px;\n  color: var(--dsw-alias-label-secondary);\n}\n.dsh_market_disclaimer {\n  color: var(--dsw-alias-label-tertiary);\n  font-size: 12px;\n  line-height: 18px;\n}\n/* The standing \"no workspace yet\" notice: the intro card's shape, but it\n   states a prerequisite rather than asking a question, so it stays quiet. */\n.dsh_market_notice {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 8px;\n  padding: 12px 16px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 10px;\n  background: var(--dsw-alias-bg-layer-2);\n}\n.dsh_market_noticeBody {\n  margin: 0;\n  font-size: 13px;\n  line-height: 20px;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh_market_introActions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-top: 4px;\n}\n\n.dsh_market_bar {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.dsh_market_search {\n  flex: 1;\n  min-width: 0;\n  box-sizing: border-box;\n  height: 36px;\n  padding: 0 12px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  outline: none;\n}\n.dsh_market_search::placeholder {\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_search:focus-visible {\n  border-color: var(--dsw-alias-state-business-primary);\n  box-shadow: 0 0 0 2px color-mix(in srgb, var(--dsw-alias-state-business-primary) 18%, transparent);\n}\n\n.dsh_market_ghost {\n  flex: none;\n  white-space: nowrap;\n  padding: 7px 16px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 28px;\n  background: none;\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 13px;\n  cursor: pointer;\n  transition: background-color .15s ease;\n}\n.dsh_market_ghost:hover:not(:disabled) {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dsh_market_ghost:disabled {\n  cursor: default;\n  opacity: .55;\n}\n\n.dsh_market_primary {\n  flex: none;\n  white-space: nowrap;\n  padding: 7px 16px;\n  border: 1px solid var(--dsw-alias-label-primary);\n  border-radius: 28px;\n  background: var(--dsw-alias-label-primary);\n  color: var(--dsw-alias-bg-layer-1);\n  font: inherit;\n  font-size: 13px;\n  cursor: pointer;\n  transition: opacity .15s ease;\n}\n.dsh_market_primary:hover:not(:disabled) {\n  opacity: .88;\n}\n.dsh_market_primary:disabled {\n  cursor: default;\n  opacity: .55;\n}\n\n.dsh_market_chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n.dsh_market_chip {\n  padding: 3px 10px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 999px;\n  background: none;\n  color: var(--dsw-alias-label-secondary);\n  font: inherit;\n  font-size: 12px;\n  line-height: 18px;\n  cursor: pointer;\n}\n.dsh_market_chip:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n}\n.dsh_market_chip[data-on=\"true\"] {\n  border-color: var(--dsw-alias-label-primary);\n  background: var(--dsw-alias-label-primary);\n  color: var(--dsw-alias-bg-layer-1);\n}\n\n.dsh_market_status {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin: 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_status[data-error=\"true\"] {\n  color: var(--dsw-alias-state-error-primary);\n}\n.dsh_market_status[aria-busy=\"true\"] {\n  color: var(--dsw-alias-label-secondary);\n}\n\n.dsh_market_cards {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  align-items: start;\n  gap: 10px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.dsh_market_card {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  min-width: 0;\n  padding: 12px 14px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 10px;\n  background: var(--dsw-alias-bg-layer-3);\n}\n.dsh_market_head {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  min-width: 0;\n}\n.dsh_market_name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  font-size: 13px;\n  font-weight: 600;\n  line-height: 20px;\n}\n.dsh_market_stars {\n  flex: none;\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsw-alias-label-tertiary);\n}\n/* \"You already have this\": carried in the accent the rest of the section uses\n   for its own state lines, so a card the user owns is distinguishable from a\n   card they do not at a glance across the grid. */\n.dsh_market_owned {\n  flex: none;\n  max-width: 45%;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  font-size: 12px;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsw-alias-state-business-primary);\n}\n/* Two cards to a row leaves about 250px of text width, which is not enough\n   for category, owner, language, licence and date on one line \u2014 so this line\n   wraps rather than ending in an ellipsis that hides the licence. */\n.dsh_market_meta {\n  margin: 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_repoIcon {\n  display: inline-flex;\n  margin-left: 5px;\n  vertical-align: -2px;\n  color: inherit;\n}\n.dsh_market_repoIcon svg {\n  width: 14px;\n  height: 14px;\n}\n.dsh_market_repoIcon:hover,\n.dsh_market_repoIcon:focus-visible {\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_desc {\n  display: -webkit-box;\n  -webkit-line-clamp: 3;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  margin: 0;\n  font-size: 13px;\n  line-height: 19px;\n  color: var(--dsw-alias-label-secondary);\n}\n.dsh_market_foot {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  margin-top: auto;\n  padding-top: 2px;\n}\n/* The disable verb reuses the section's ghost button, which is sized for the\n   page chrome (enable/refresh). In this row it must match the uninstall\n   control beside it \u2014 same padding, type size, and line box. */\n.dsh_market_foot .dsh_market_ghost {\n  padding: 4px 12px;\n  font-size: 12px;\n  line-height: 18px;\n  border-radius: 999px;\n}\n.dsh_market_link {\n  flex: none;\n  padding: 4px 10px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 999px;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  text-decoration: none;\n}\n.dsh_market_link:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n.dsh_market_install {\n  flex: none;\n  padding: 4px 12px;\n  border: 1px solid var(--dsw-alias-label-primary);\n  border-radius: 999px;\n  background: var(--dsw-alias-label-primary);\n  color: var(--dsw-alias-bg-layer-1);\n  font: inherit;\n  font-size: 12px;\n  cursor: pointer;\n  transition: opacity .15s ease;\n}\n.dsh_market_install:hover:not(:disabled) {\n  opacity: .88;\n}\n.dsh_market_install:disabled {\n  cursor: default;\n  opacity: .55;\n}\n/* The confirmation replaces the row's actions, so the card reports what\n   happened where the button that caused it was. */\n.dsh_market_staged {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  margin-top: auto;\n  padding-top: 6px;\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh_market_stagedTitle {\n  color: var(--dsw-alias-state-business-primary);\n}\n.dsh_market_stagedHint,\n.dsh_market_cardError {\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_cardError {\n  color: var(--dsw-alias-state-error-primary);\n}\n/* A missing workspace is a prerequisite, not a failure \u2014 the card says it in\n   the ordinary secondary voice and keeps its action next to it. */\n.dsh_market_cardNotice {\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  line-height: 18px;\n}\n\n.dsh_market_note {\n  margin: 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_note a {\n  color: inherit;\n  text-decoration: underline;\n  cursor: pointer;\n}\n\n/* The installed set renders in the same card as the catalog rows, so it needs\n   no layout of its own \u2014 only the few marks a shopfront card has no use for:\n   the explanatory line above the grid, and the live state badge in each\n   card's head. */\n.dsh_market_installedBody {\n  margin: 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_installedNotice {\n  margin: 0;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-state-business-primary);\n}\n/* The desktop-seat hint: an inline \u24D8 whose explanation pops on hover or\n   keyboard focus. A tooltip rather than a standing paragraph because the\n   text answers a question most viewings never ask. */\n.dsh_market_hint {\n  position: relative;\n  display: inline-flex;\n  margin-left: 5px;\n  vertical-align: -2px;\n  color: var(--dsw-alias-label-tertiary);\n  cursor: help;\n  outline: none;\n}\n.dsh_market_hint svg {\n  width: 13px;\n  height: 13px;\n}\n.dsh_market_hint:hover,\n.dsh_market_hint:focus-visible {\n  color: var(--dsw-alias-label-secondary);\n}\n.dsh_market_hintTip {\n  position: absolute;\n  bottom: calc(100% + 8px);\n  /* Anchored to the icon's RIGHT edge, growing leftward. Centering reads\n     nicer but overflows the dialog whenever the icon sits in a right-column\n     card \u2014 which the seat card usually does, listed after the dependency\n     installs. Leftward growth stays inside: the meta line guarantees more\n     room on that side than the tip is wide. */\n  right: -8px;\n  z-index: 30;\n  width: 264px;\n  padding: 8px 10px;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-3);\n  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.14);\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-secondary);\n  text-align: left;\n  pointer-events: none;\n  opacity: 0;\n  transition: opacity 0.12s;\n}\n.dsh_market_hint:hover .dsh_market_hintTip,\n.dsh_market_hint:focus-visible .dsh_market_hintTip {\n  opacity: 1;\n}\n.dsh_market_installedState {\n  flex: none;\n  margin-left: auto;\n  font-size: 12px;\n  line-height: 18px;\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_installedState[data-state=\"running\"] {\n  color: var(--dsw-alias-state-success-primary, var(--dsw-alias-state-business-primary));\n}\n.dsh_market_installedState[data-state=\"disabled\"],\n.dsh_market_installedState[data-state=\"unregistered\"] {\n  color: var(--dsw-alias-label-tertiary);\n}\n.dsh_market_installedState[data-state=\"failed\"],\n.dsh_market_installedState[data-state=\"readFailed\"] {\n  color: var(--dsw-alias-state-error-primary);\n}\n\n/* The uninstall verb: outlined in the error color so the destructive action\n   reads as such without filling the row. */\n.dsh_market_danger {\n  flex: none;\n  white-space: nowrap;\n  padding: 4px 12px;\n  border: 1px solid var(--dsw-alias-state-error-primary);\n  border-radius: 999px;\n  background: none;\n  color: var(--dsw-alias-state-error-primary);\n  font: inherit;\n  font-size: 12px;\n  line-height: 18px;\n  cursor: pointer;\n  transition: background-color .15s ease;\n}\n.dsh_market_danger:hover:not(:disabled) {\n  background: color-mix(in srgb, var(--dsw-alias-state-error-primary) 10%, transparent);\n}\n.dsh_market_danger:disabled {\n  cursor: default;\n  opacity: .55;\n}\n";
